export interface BaseRecord {
  id: string;
  createdAt: string;
  updatedAt: string;
}

export const RESUME_STATUSES = [
  "ready",
  "extraction-failed",
  "needs-review",
  "deleted",
] as const;
export type ResumeStatus = (typeof RESUME_STATUSES)[number];

export const INTERVIEW_STATUSES = [
  "scheduled",
  "completed",
  "cancelled",
  "rescheduled",
] as const;
export type InterviewStatus = (typeof INTERVIEW_STATUSES)[number];

export const STAGE_KINDS = [
  "normal",
  "offer",
  "rejected",
  "withdrawn",
] as const;
export type StageKind = (typeof STAGE_KINDS)[number];

export interface Resume extends BaseRecord {
  name: string;
  type: "pdf" | "docx";
  fileName: string;
  fileSize: number;
  fileHash: string;
  uploadedAt: string;
  tags: string[];
  note: string;
  status: ResumeStatus;
  textSource?: "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type ResumeTextKind = "extracted" | "confirmed" | "manual";

export interface ResumeText extends BaseRecord {
  resumeId: string;
  kind: ResumeTextKind;
  text: string;
  confirmedAt?: string;
}

export interface JobDescription extends BaseRecord {
  applicationId: string;
  fileName?: string;
  fileType?: "pdf" | "docx";
  fileSize?: number;
  fileHash?: string;
  textSource: "pasted" | "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type JobDescriptionTextKind =
  | "pasted"
  | "extracted"
  | "confirmed"
  | "manual";

export interface JobDescriptionText extends BaseRecord {
  jobDescriptionId: string;
  kind: JobDescriptionTextKind;
  text: string;
  confirmedAt?: string;
}

export interface Application extends BaseRecord {
  company: string;
  position: string;
  jobType: "graduate" | "internship" | "tech" | "general" | "other";
  location: string;
  workMode: "onsite" | "remote" | "hybrid" | "unknown";
  salaryText: string;
  source: string;
  jobUrl: string;
  jdText: string;
  jdFileId?: string;
  currentResumeId?: string;
  stageId: string;
  priority: number;
  deadline?: string;
  contact: string;
  note: string;
  archivedAt?: string;
}

export interface ResumeUsageHistory extends BaseRecord {
  applicationId: string;
  resumeId: string;
  resumeNameSnapshot: string;
  textSnapshot: string;
  usedAt: string;
}

export interface Stage extends BaseRecord {
  name: string;
  color: string;
  order: number;
  kind: StageKind;
}

export type TimelineEventType =
  | "stage-changed"
  | "resume-changed"
  | "note-added"
  | "archived"
  | "interview-rescheduled";

export interface ApplicationTimelineEvent extends BaseRecord {
  applicationId: string;
  type: TimelineEventType;
  fromValue?: string;
  toValue?: string;
  note: string;
}

export interface Reminder {
  offsetMinutes: number;
  channel: "in-app" | "browser";
}

export interface Interview extends BaseRecord {
  applicationId: string;
  round: number;
  type: "phone" | "video" | "onsite" | "assessment" | "other";
  title: string;
  startsAt: string;
  endsAt?: string;
  timezone: string;
  locationOrLink: string;
  interviewer: string;
  status: InterviewStatus;
  reminders: Reminder[];
  calendarExportedAt?: string;
  note: string;
}

export interface ReviewQuestion {
  question: string;
  answer?: string;
  note?: string;
}

export interface InterviewReview extends BaseRecord {
  interviewId: string;
  overallRating?: number;
  questions: ReviewQuestion[];
  goodAnswers: string;
  weakAnswers: string;
  observedSignals: string;
  salaryDiscussion: string;
  nextStep: string;
  privateNote: string;
}

export interface ReminderFailure extends BaseRecord {
  interviewId: string;
  reminderAt: string;
  reason: string;
}

export interface AnalysisCoverage {
  overall: number;
  required: number;
  preferred: number;
}

export interface AnalysisEvidence {
  keyword: string;
  excerpt: string;
}

export interface AnalysisResult extends BaseRecord {
  applicationId: string;
  resumeId: string;
  mode: "local" | "ai";
  coverage: AnalysisCoverage;
  matchedKeywords: string[];
  weakMatches: string[];
  missingKeywords: string[];
  evidence: AnalysisEvidence[];
  uncertainItems: string[];
  recommendations: string[];
}

export interface AiMessage {
  id: string;
  role: "system" | "user" | "assistant";
  content: string;
  createdAt: string;
}

export interface AiConversation extends BaseRecord {
  applicationId: string;
  messages: AiMessage[];
}

export interface StoredFile extends BaseRecord {
  ownerType: "resume" | "job-description";
  ownerId: string;
  fileName: string;
  fileType: "pdf" | "docx";
  blob: Blob;
}

export interface SensitiveSettingsRecord extends BaseRecord {
  id: "ai";
  apiUrl: string;
  model: string;
  apiKey: string;
  organizationId: string;
  customHeaders: Record<string, string>;
}

export interface DomainRecordMap {
  resumes: Resume;
  resumeTexts: ResumeText;
  jobDescriptions: JobDescription;
  jobDescriptionTexts: JobDescriptionText;
  applications: Application;
  resumeUsageHistory: ResumeUsageHistory;
  stages: Stage;
  applicationTimelineEvents: ApplicationTimelineEvent;
  interviews: Interview;
  interviewReviews: InterviewReview;
  analysisResults: AnalysisResult;
  aiConversations: AiConversation;
  reminderFailures: ReminderFailure;
  originalFiles: StoredFile;
}

export type DomainStoreName = keyof DomainRecordMap;
export const DATABASE_NAME = "local-career-workspace";
export const DATABASE_VERSION = 6;

export const STORE_NAMES = {
  resumes: "resumes",
  resumeTexts: "resumeTexts",
  jobDescriptions: "jobDescriptions",
  jobDescriptionTexts: "jobDescriptionTexts",
  applications: "applications",
  resumeUsageHistory: "resumeUsageHistory",
  stages: "stages",
  applicationTimelineEvents: "applicationTimelineEvents",
  interviews: "interviews",
  interviewReviews: "interviewReviews",
  analysisResults: "analysisResults",
  aiConversations: "aiConversations",
  reminderFailures: "reminderFailures",
  originalFiles: "originalFiles",
  sensitiveSettings: "sensitiveSettings",
} as const;

export type StoreName = (typeof STORE_NAMES)[keyof typeof STORE_NAMES];

interface IndexDefinition {
  name: string;
  keyPath: string | string[];
  unique?: boolean;
}

const INDEXES: Record<StoreName, readonly IndexDefinition[]> = {
  resumes: [
    { name: "status", keyPath: "status" },
    { name: "fileHash", keyPath: "fileHash" },
    { name: "updatedAt", keyPath: "updatedAt" },
  ],
  resumeTexts: [
    { name: "resumeId", keyPath: "resumeId" },
    { name: "resumeId_kind", keyPath: ["resumeId", "kind"], unique: true },
  ],
  jobDescriptions: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "fileHash", keyPath: "fileHash" },
  ],
  jobDescriptionTexts: [
    { name: "jobDescriptionId", keyPath: "jobDescriptionId" },
    {
      name: "jobDescriptionId_kind",
      keyPath: ["jobDescriptionId", "kind"],
      unique: true,
    },
  ],
  applications: [
    { name: "stageId", keyPath: "stageId" },
    { name: "currentResumeId", keyPath: "currentResumeId" },
    { name: "updatedAt", keyPath: "updatedAt" },
  ],
  resumeUsageHistory: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "resumeId", keyPath: "resumeId" },
  ],
  stages: [
    { name: "kind", keyPath: "kind" },
    { name: "order", keyPath: "order" },
  ],
  applicationTimelineEvents: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "createdAt", keyPath: "createdAt" },
  ],
  interviews: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "startsAt", keyPath: "startsAt" },
    { name: "status", keyPath: "status" },
  ],
  interviewReviews: [
    { name: "interviewId", keyPath: "interviewId", unique: true },
  ],
  analysisResults: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "resumeId", keyPath: "resumeId" },
    { name: "createdAt", keyPath: "createdAt" },
  ],
  aiConversations: [{ name: "applicationId", keyPath: "applicationId" }],
  reminderFailures: [
    { name: "interviewId", keyPath: "interviewId" },
    { name: "reminderAt", keyPath: "reminderAt" },
  ],
  originalFiles: [
    { name: "ownerId", keyPath: "ownerId" },
    {
      name: "ownerType_ownerId",
      keyPath: ["ownerType", "ownerId"],
      unique: true,
    },
  ],
  sensitiveSettings: [],
};

export function ensureSchema(
  database: IDBDatabase,
  transaction: IDBTransaction,
): void {
  for (const storeName of Object.values(STORE_NAMES)) {
    const store = database.objectStoreNames.contains(storeName)
      ? transaction.objectStore(storeName)
      : database.createObjectStore(storeName, { keyPath: "id" });

    for (const index of INDEXES[storeName]) {
      if (!store.indexNames.contains(index.name)) {
        store.createIndex(index.name, index.keyPath, {
          unique: index.unique ?? false,
        });
      }
    }
  }
}
import { requestToPromise, runTransaction } from "./database";
import { STORE_NAMES, type StoreName } from "./schema";
import {
  assertAbsoluteIsoTimestamp,
  nextUpdatedTimestamp,
} from "./timestamps";
import {
  INTERVIEW_STATUSES,
  RESUME_STATUSES,
  STAGE_KINDS,
  type AiConversation,
  type AnalysisResult,
  type Application,
  type ApplicationTimelineEvent,
  type BaseRecord,
  type Interview,
  type InterviewReview,
  type ReminderFailure,
  type JobDescription,
  type JobDescriptionText,
  type Resume,
  type ResumeText,
  type ResumeUsageHistory,
  type Stage,
} from "./types";

export type CreateInput<T extends BaseRecord> = Omit<
  T,
  "id" | "createdAt" | "updatedAt"
>;
export type UpdateInput<T extends BaseRecord> = Partial<T>;

export interface Repository<T extends BaseRecord> {
  create(input: CreateInput<T>): Promise<T>;
  get(id: string): Promise<T | undefined>;
  list(): Promise<T[]>;
  update(id: string, patch: UpdateInput<T>): Promise<T>;
  delete(id: string): Promise<void>;
  findByIndex(indexName: string, query: IDBValidKey | IDBKeyRange): Promise<T[]>;
}

export interface RepositoryDependencies {
  now?: () => string;
  createId?: () => string;
}

type Validator<T extends BaseRecord> = (record: T) => void;

function defaultCreateId(): string {
  return crypto.randomUUID();
}

function defaultNow(): string {
  return new Date().toISOString();
}

function nextTimestamp(candidate: string, previous: string): string {
  return nextUpdatedTimestamp(candidate, previous);
}

function includes<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === "string" && values.includes(value as T);
}

function validateBase(record: BaseRecord): void {
  if (!record.id) {
    throw new Error("Invalid record id");
  }
  assertAbsoluteIsoTimestamp(record.createdAt, "createdAt");
  assertAbsoluteIsoTimestamp(record.updatedAt, "updatedAt");
}

function validateResume(record: Resume): void {
  if (!includes(RESUME_STATUSES, record.status)) {
    throw new Error("Invalid Resume.status");
  }
}

function validateStage(record: Stage): void {
  if (!includes(STAGE_KINDS, record.kind)) {
    throw new Error("Invalid Stage.kind");
  }
}

function validateTimezone(timezone: string): void {
  try {
    new Intl.DateTimeFormat("en", { timeZone: timezone }).format();
  } catch {
    throw new Error("Invalid Interview.timezone");
  }
}

function validateInterview(record: Interview): void {
  if (!includes(INTERVIEW_STATUSES, record.status)) {
    throw new Error("Invalid Interview.status");
  }
  assertAbsoluteIsoTimestamp(record.startsAt, "Interview.startsAt");
  if (record.endsAt !== undefined) {
    assertAbsoluteIsoTimestamp(record.endsAt, "Interview.endsAt");
  }
  validateTimezone(record.timezone);
  if (!Number.isInteger(record.round) || record.round < 1) throw new Error("Invalid Interview.round");
  if (record.endsAt !== undefined && Date.parse(record.endsAt) <= Date.parse(record.startsAt)) throw new Error("Invalid Interview.endsAt");
  if (!Array.isArray(record.reminders)) throw new Error("Invalid Interview.reminders");
  for (const reminder of record.reminders) {
    if (!Number.isInteger(reminder.offsetMinutes) || reminder.offsetMinutes <= 0 || !["in-app", "browser"].includes(reminder.channel)) throw new Error("Invalid Interview.reminder");
  }
}

class IndexedDbRepository<T extends BaseRecord> implements Repository<T> {
  readonly #database: IDBDatabase;
  readonly #storeName: StoreName;
  readonly #now: () => string;
  readonly #createId: () => string;
  readonly #validate?: Validator<T>;

  constructor(
    database: IDBDatabase,
    storeName: StoreName,
    dependencies: Required<RepositoryDependencies>,
    validate?: Validator<T>,
  ) {
    this.#database = database;
    this.#storeName = storeName;
    this.#now = dependencies.now;
    this.#createId = dependencies.createId;
    this.#validate = validate;
  }

  async create(input: CreateInput<T>): Promise<T> {
    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "createdAt");
    const record = {
      ...input,
      id: this.#createId(),
      createdAt: timestamp,
      updatedAt: timestamp,
    } as T;
    validateBase(record);
    this.#validate?.(record);

    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
      requestToPromise(transaction.objectStore(this.#storeName).add(record)),
    );
    return record;
  }

  get(id: string): Promise<T | undefined> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T | undefined>(
        transaction.objectStore(this.#storeName).get(id),
      ),
    );
  }

  list(): Promise<T[]> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T[]>(transaction.objectStore(this.#storeName).getAll()),
    );
  }

  async update(id: string, patch: UpdateInput<T>): Promise<T> {
    return runTransaction(this.#database, this.#storeName, "readwrite", async (transaction) => {
      const store = transaction.objectStore(this.#storeName);
      const existing = await requestToPromise<T | undefined>(store.get(id));
      if (!existing) {
        throw new Error(`Record not found: ${id}`);
      }

      const updated = {
        ...existing,
        ...patch,
        id: existing.id,
        createdAt: existing.createdAt,
        updatedAt: nextTimestamp(this.#now(), existing.updatedAt),
      };
      validateBase(updated);
      this.#validate?.(updated);
      await requestToPromise(store.put(updated));
      return updated;
    });
  }

  async delete(id: string): Promise<void> {
    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
      requestToPromise(transaction.objectStore(this.#storeName).delete(id)),
    );
  }

  findByIndex(
    indexName: string,
    query: IDBValidKey | IDBKeyRange,
  ): Promise<T[]> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T[]>(
        transaction.objectStore(this.#storeName).index(indexName).getAll(query),
      ),
    );
  }
}

export interface DomainRepositories {
  resumes: Repository<Resume>;
  resumeTexts: Repository<ResumeText>;
  jobDescriptions: Repository<JobDescription>;
  jobDescriptionTexts: Repository<JobDescriptionText>;
  applications: Repository<Application>;
  resumeUsageHistory: Repository<ResumeUsageHistory>;
  stages: Repository<Stage>;
  applicationTimelineEvents: Repository<ApplicationTimelineEvent>;
  interviews: Repository<Interview>;
  interviewReviews: Repository<InterviewReview>;
  analysisResults: Repository<AnalysisResult>;
  aiConversations: Repository<AiConversation>;
  reminderFailures: Repository<ReminderFailure>;
}

export function createRepositories(
  database: IDBDatabase,
  dependencies: RepositoryDependencies = {},
): DomainRepositories {
  const resolvedDependencies: Required<RepositoryDependencies> = {
    now: dependencies.now ?? defaultNow,
    createId: dependencies.createId ?? defaultCreateId,
  };
  const repository = <T extends BaseRecord>(
    storeName: StoreName,
    validate?: Validator<T>,
  ): Repository<T> =>
    new IndexedDbRepository(database, storeName, resolvedDependencies, validate);

  return {
    resumes: repository(STORE_NAMES.resumes, validateResume),
    resumeTexts: repository(STORE_NAMES.resumeTexts),
    jobDescriptions: repository(STORE_NAMES.jobDescriptions),
    jobDescriptionTexts: repository(STORE_NAMES.jobDescriptionTexts),
    applications: repository(STORE_NAMES.applications),
    resumeUsageHistory: repository(STORE_NAMES.resumeUsageHistory),
    stages: repository(STORE_NAMES.stages, validateStage),
    applicationTimelineEvents: repository(
      STORE_NAMES.applicationTimelineEvents,
    ),
    interviews: repository(STORE_NAMES.interviews, validateInterview),
    interviewReviews: repository(STORE_NAMES.interviewReviews),
    analysisResults: repository(STORE_NAMES.analysisResults),
    aiConversations: repository(STORE_NAMES.aiConversations),
    reminderFailures: repository(STORE_NAMES.reminderFailures),
  };
}

import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import {
  assertAbsoluteIsoTimestamp,
  nextUpdatedTimestamp,
} from "../../db/timestamps";
