const PREFERRED_MARKERS = /(?:加分项?|优先(?:考虑|条件)?|更佳|preferred|nice\s+to\s+have|bonus|a\s+plus)/iu;
const REQUIRED_MARKERS = /(?:任职要求|岗位要求|必须|必需|要求|精通|熟练|required|requirements?|must|minimum)/iu;
const EXPERIENCE_PATTERN = /(?:\d+(?:\.\d+)?\s*(?:年|years?)\s*(?:(?:以上|及以上|\+|or\s+more|min(?:imum)?\.?)\s*)?(?:[^。；;,，\n]{0,12})?(?:经验|experience))/giu;
const RESPONSIBILITY_PATTERN = /^(?:负责|承担|主导|设计|开发|维护|管理|lead(?:ing)?|design(?:ing)?|develop(?:ing)?|build(?:ing)?|maintain(?:ing)?|manage(?:ment|ing)?)(?:\s|[:：])*(.+)$/iu;

export function normalizeText(value: string): string {
  return value
    .normalize("NFKC")
    .toLocaleLowerCase("en-US")
    .replace(/[^\p{L}\p{N}+#]+/gu, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function comparisonKey(value: string): string {
  return normalizeText(value).replace(/\s+/g, "");
}

function catalogEntryFor(value: string): CatalogEntry | undefined {
  const key = comparisonKey(value);
  return CATALOG.find((entry) =>
    entry.forms.some((form) => comparisonKey(form) === key),
  );
}

export function normalizeKeyword(
  original: string,
  options: KeywordOptions = {},
): KeywordDefinition {
  const displayForm = original.trim();
  const entry = catalogEntryFor(displayForm);
  const normalized = normalizeText(displayForm);
  return {
    original: displayForm,
    normalized,
    canonical: entry?.canonical ?? normalized,
    category: options.category ?? entry?.category ?? "skill",
    requirement: options.requirement ?? "required",
    aliases: (entry?.forms ?? [displayForm])
      .map(normalizeText)
      .filter((form, index, forms) => form && forms.indexOf(form) === index),
  };
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function formPattern(form: string): RegExp {
  const normalized = normalizeText(form);
  const parts = normalized.split(" ").map(escapeRegExp);
  const source = parts.join("[\\s\\p{P}_]*");
  const latinStart = /^[a-z0-9]/iu.test(normalized);
  const latinEnd = /[a-z0-9]$/iu.test(normalized);
  return new RegExp(
    `${latinStart ? "(?<![a-z0-9])" : ""}${source}${latinEnd ? "(?![a-z0-9])" : ""}`,
    "iu",
  );
}

function locateCatalogEntries(line: string): LocatedCatalogEntry[] {
  const candidates: LocatedCatalogEntry[] = [];
  for (const entry of CATALOG) {
    for (const form of entry.forms) {
      const match = formPattern(form).exec(line.normalize("NFKC"));
      if (!match?.[0]) continue;
      candidates.push({
        entry,
        start: match.index,
        end: match.index + match[0].length,
        original: line.slice(match.index, match.index + match[0].length),
      });
    }
  }

  candidates.sort((left, right) => {
    const lengthDifference = right.end - right.start - (left.end - left.start);
    return lengthDifference || left.start - right.start;
  });
  const selected: LocatedCatalogEntry[] = [];
  for (const candidate of candidates) {
    const overlaps = selected.some(
      (item) => candidate.start < item.end && candidate.end > item.start,
    );
    if (!overlaps && !selected.some((item) => item.entry.canonical === candidate.entry.canonical)) {
      selected.push(candidate);
    }
  }
  return selected.sort((left, right) => left.start - right.start);
}

function cleanedLine(line: string): string {
  return line
    .replace(/^\s*(?:[-*•·]|\d+[.)、])\s*/, "")
    .replace(/[。；;，,\s]+$/u, "")
    .trim();
}

function lineRequirement(line: string, section: KeywordRequirement): KeywordRequirement {
  if (PREFERRED_MARKERS.test(line)) return "preferred";
  if (REQUIRED_MARKERS.test(line)) return "required";
  return section;
}

function requirementForRange(
  line: string,
  start: number,
  end: number,
  section: KeywordRequirement,
): KeywordRequirement {
  // Requirement markers apply to the punctuation-delimited clause containing
  // the keyword, rather than leaking across a line of independent clauses.
  const delimiter = /[;；。！？!?，,]/u;
  let clauseStart = start;
  while (clauseStart > 0 && !delimiter.test(line[clauseStart - 1] ?? "")) {
    clauseStart -= 1;
  }
  let clauseEnd = end;
  while (clauseEnd < line.length && !delimiter.test(line[clauseEnd] ?? "")) {
    clauseEnd += 1;
  }
  return lineRequirement(line.slice(clauseStart, clauseEnd), section);
}

function pushUnique(target: KeywordDefinition[], keyword: KeywordDefinition): void {
  const duplicate = target.some(
    (item) => item.canonical === keyword.canonical && item.category === keyword.category,
  );
  if (!duplicate) target.push(keyword);
}

export function extractKeywords(jdText: string): KeywordDefinition[] {
  const result: KeywordDefinition[] = [];
  let section: KeywordRequirement = "required";

  for (const rawLine of jdText.split(/\r?\n/)) {
    const line = cleanedLine(rawLine);
    if (!line) continue;
    if (PREFERRED_MARKERS.test(line) && /^(?:加分项?|优先条件|preferred|nice\s+to\s+have)/iu.test(line)) {
      section = "preferred";
      if (!/[:：]\s*\S/u.test(line)) continue;
    } else if (REQUIRED_MARKERS.test(line) && /^(?:任职要求|岗位要求|requirements?)/iu.test(line)) {
      section = "required";
      if (!/[:：]\s*\S/u.test(line)) continue;
    }

    for (const located of locateCatalogEntries(line)) {
      pushUnique(
        result,
        normalizeKeyword(located.original, {
          category: located.entry.category,
          requirement: requirementForRange(line, located.start, located.end, section),
        }),
      );
    }

    for (const match of line.matchAll(EXPERIENCE_PATTERN)) {
      pushUnique(
        result,
        normalizeKeyword(match[0], {
          category: "experience",
          requirement: requirementForRange(
            line,
            match.index ?? 0,
            (match.index ?? 0) + match[0].length,
            section,
          ),
        }),
      );
    }

    const responsibility = RESPONSIBILITY_PATTERN.exec(line);
    if (responsibility) {
      const original = line.replace(/[。；;，,\s]+$/u, "");
      pushUnique(
        result,
        normalizeKeyword(original, {
          category: "responsibility",
          requirement: requirementForRange(line, 0, line.length, section),
        }),
      );
    }
  }
  return result;
}

export function groupKeywords(keywords: readonly KeywordDefinition[]): KeywordGroups {
  const groups = Object.fromEntries(
    KEYWORD_CATEGORIES.map((category) => [category, []]),
  ) as unknown as KeywordGroups;
  for (const keyword of keywords) groups[keyword.category].push({ ...keyword });
  return groups;

export const KEYWORD_CATEGORIES = [
  "skill",
  "tool",
  "framework",
  "platform",
  "general-ability",
  "education",
  "certification",
  "language",
  "experience",
  "responsibility",
] as const;

export type KeywordCategory = (typeof KEYWORD_CATEGORIES)[number];
export type KeywordRequirement = "required" | "preferred";
export type KeywordMatchStatus =
  | "exact"
  | "synonym"
  | "weak-context"
  | "missing"
  | "needs-review";

export interface KeywordDefinition {
  original: string;
  normalized: string;
  canonical: string;
  category: KeywordCategory;
  requirement: KeywordRequirement;
  aliases: readonly string[];
}

export type KeywordGroups = Record<KeywordCategory, KeywordDefinition[]>;

export interface KeywordMatch extends KeywordDefinition {
  status: KeywordMatchStatus;
  evidence?: string;
  uncertain: boolean;
}

export interface CoverageDetail {
  earned: number;
  total: number;
  percentage: number;
}

export interface MatchCoverage {
  overall: number;
  required: number;
  preferred: number;
}

export interface MatchCoverageDetails {
  overall: CoverageDetail;
  required: CoverageDetail;
  preferred: CoverageDetail;
}

export interface LocalMatchResult {
  coverage: MatchCoverage;
  coverageDetails: MatchCoverageDetails;
  items: KeywordMatch[];
  matched: KeywordMatch[];
  weakMatches: KeywordMatch[];
  missing: KeywordMatch[];
  needsReview: KeywordMatch[];
  matchedKeywords: string[];
  missingKeywords: string[];
  uncertainItems: string[];
  evidence: Array<{ keyword: string; excerpt: string }>;
  recommendations: string[];
  disclaimer: string;
}
import { extractKeywords, normalizeText } from "./normalization";
import type {
  CoverageDetail,
  KeywordDefinition,
  KeywordMatch,
  KeywordRequirement,
  LocalMatchResult,
} from "./types";

interface LocatedText {
  start: number;
  end: number;
}

interface SearchDocument {
  normalized: string;
  sourceIndexes: number[];
}

const WEAK_CONTEXT = /(?:正在学习|学习中|初学|入门|尚无|暂无|了解过|接触过|learning|beginner|basic\s+(?:knowledge|understanding)|exposure\s+to|no\s+(?:production|professional))/iu;
const EXPERIENCE_EVIDENCE = /(?:(?:19|20)\d{2}|至今|目前|年经验|years?\s+(?:of\s+)?experience)/iu;
const DISCLAIMER = "匹配结果仅代表简历与 JD 中可核验的文本证据，不代表用户真实具备相关能力。";

function buildSearchDocument(source: string): SearchDocument {
  let normalized = "";
  const sourceIndexes: number[] = [];
  let lastWasSpace = true;

  for (let index = 0; index < source.length; ) {
    const codePoint = source.codePointAt(index);
    if (codePoint === undefined) break;
    const character = String.fromCodePoint(codePoint);
    const width = character.length;
    const folded = character.normalize("NFKC").toLocaleLowerCase("en-US");
    for (const foldedCharacter of folded) {
      if (/^[\p{L}\p{N}+#]$/u.test(foldedCharacter)) {
        normalized += foldedCharacter;
        sourceIndexes.push(index);
        lastWasSpace = false;
      } else if (!lastWasSpace) {
        normalized += " ";
        sourceIndexes.push(index);
        lastWasSpace = true;
      }
    }
    index += width;
  }
  if (normalized.endsWith(" ")) {
    normalized = normalized.slice(0, -1);
    sourceIndexes.pop();
  }
  return { normalized, sourceIndexes };
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function searchPattern(term: string): RegExp | undefined {
  const normalized = normalizeText(term);
  if (!normalized) return undefined;
  const source = normalized.split(" ").map(escapeRegExp).join("\\s*");
  const startsWithLatin = /^[a-z0-9]/u.test(normalized);
  const endsWithLatin = /[a-z0-9]$/u.test(normalized);
  return new RegExp(
    `${startsWithLatin ? "(?<![a-z0-9])" : ""}${source}${endsWithLatin ? "(?![a-z0-9])" : ""}`,
    "iu",
  );
}

function locate(document: SearchDocument, term: string): LocatedText | undefined {
  const pattern = searchPattern(term);
  const match = pattern?.exec(document.normalized);
  if (!match?.[0]) return undefined;
  const normalizedEnd = match.index + match[0].length - 1;
  const start = document.sourceIndexes[match.index];
  const finalSourceIndex = document.sourceIndexes[normalizedEnd];
  if (start === undefined || finalSourceIndex === undefined) return undefined;
  return { start, end: finalSourceIndex + 1 };
}

function excerptAt(source: string, location: LocatedText): string {
  const boundary = /[\n。！？!?；;]/u;
  let start = location.start;
  let end = location.end;
  while (start > 0 && !boundary.test(source[start - 1] ?? "")) start -= 1;
  while (end < source.length && !boundary.test(source[end] ?? "")) end += 1;
  const full = source.slice(start, end).trim();
  if (full.length <= 180) return full;
  const localStart = Math.max(0, location.start - start - 70);
  return full.slice(localStart, localStart + 180).trim();
}

function locateExact(document: SearchDocument, keyword: KeywordDefinition): LocatedText | undefined {
  return locate(document, keyword.original);
}

function locateAlias(document: SearchDocument, keyword: KeywordDefinition): LocatedText | undefined {
  const originalKey = normalizeText(keyword.original).replace(/\s+/g, "");
  for (const alias of keyword.aliases) {
    if (normalizeText(alias).replace(/\s+/g, "") === originalKey) continue;
    const location = locate(document, alias);
    if (location) return location;
  }
  return undefined;
}

function meaningfulResponsibilityTerms(original: string): string[] {
  const withoutVerb = original.replace(
    /^(?:负责|承担|主导|设计|开发|维护|管理|lead(?:ing)?|design(?:ing)?|develop(?:ing)?|build(?:ing)?|maintain(?:ing)?|manage(?:ment|ing)?)\s*/iu,
    "",
  );
  return withoutVerb
    .split(/(?:与|和|及|、|\/|\band\b)/iu)
    .map((term) => term.trim())
    .filter((term) => normalizeText(term).length >= 2);
}

function findReviewEvidence(
  resumeText: string,
  document: SearchDocument,
  keyword: KeywordDefinition,
): LocatedText | undefined {
  if (keyword.category === "experience") {
    const match = EXPERIENCE_EVIDENCE.exec(resumeText);
    if (!match?.[0] || match.index === undefined) return undefined;
    return { start: match.index, end: match.index + match[0].length };
  }
  if (keyword.category === "responsibility") {
    for (const term of meaningfulResponsibilityTerms(keyword.original)) {
      const location = locate(document, term);
      if (location) return location;
    }
  }
  return undefined;
}

function matchKeyword(
  resumeText: string,
  document: SearchDocument,
  keyword: KeywordDefinition,
): KeywordMatch {
  const exact = locateExact(document, keyword);
  if (exact) {
    const evidence = excerptAt(resumeText, exact);
    const weak = WEAK_CONTEXT.test(evidence);
    return {
      ...keyword,
      status: weak ? "weak-context" : "exact",
      evidence,
      uncertain: weak,
    };
  }

  const synonym = locateAlias(document, keyword);
  if (synonym) {
    const evidence = excerptAt(resumeText, synonym);
    const weak = WEAK_CONTEXT.test(evidence);
    return {
      ...keyword,
      status: weak ? "weak-context" : "synonym",
      evidence,
      uncertain: weak,
    };
  }

  const reviewEvidence = findReviewEvidence(resumeText, document, keyword);
  if (reviewEvidence) {
    return {
      ...keyword,
      status: "needs-review",
      evidence: excerptAt(resumeText, reviewEvidence),
      uncertain: true,
    };
  }

  return { ...keyword, status: "missing", uncertain: false };
}

function weight(item: KeywordMatch): number {
  if (item.status === "exact" || item.status === "synonym") return 1;
  if (item.status === "weak-context") return 0.5;
  return 0;
}

function coverageDetail(items: readonly KeywordMatch[]): CoverageDetail {
  const earned = items.reduce((sum, item) => sum + weight(item), 0);
  const total = items.length;
  const percentage = total === 0 ? 0 : Math.round((earned / total) * 10_000) / 100;
  return { earned, total, percentage };
}

function byRequirement(
  items: readonly KeywordMatch[],
  requirement: KeywordRequirement,
): KeywordMatch[] {
  return items.filter((item) => item.requirement === requirement);
}

export function scoreKeywords(
  resumeText: string,
  keywords: readonly KeywordDefinition[],
): LocalMatchResult {
  const document = buildSearchDocument(resumeText);
  const items = keywords.map((keyword) => matchKeyword(resumeText, document, keyword));
  const matched = items.filter(
    (item) => item.status === "exact" || item.status === "synonym",
  );
  const weakMatches = items.filter((item) => item.status === "weak-context");
  const missing = items.filter((item) => item.status === "missing");
  const needsReview = items.filter((item) => item.status === "needs-review");
  const overall = coverageDetail(items);
  const required = coverageDetail(byRequirement(items, "required"));
  const preferred = coverageDetail(byRequirement(items, "preferred"));
  const evidence = items.flatMap((item) =>
    item.evidence ? [{ keyword: item.original, excerpt: item.evidence }] : [],
  );

  return {
    coverage: {
      overall: overall.percentage,
      required: required.percentage,
      preferred: preferred.percentage,
    },
    coverageDetails: { overall, required, preferred },
    items,
    matched,
    weakMatches,
    missing,
    needsReview,
    matchedKeywords: matched.map((item) => item.original),
    missingKeywords: missing.map((item) => item.original),
    uncertainItems: [...weakMatches, ...needsReview].map((item) => item.original),
    evidence,
    recommendations: [],
    disclaimer: DISCLAIMER,
  };
}

export function runLocalMatch(jdText: string, resumeText: string): LocalMatchResult {
  return scoreKeywords(resumeText, extractKeywords(jdText));
}

export const matchJobDescription = runLocalMatch;

import type { ResumeLibraryService } from "../../features/resumes/resumeLibrary";
import type { Application, Resume, Stage } from "../../db/types";

export interface ApplicationBoardOptions {
  applicationService?: {
    listApplications(): Promise<Application[]>;
    createApplication(input: Record<string, unknown>): Promise<Application>;
    updateApplication(id: string, patch: Record<string, unknown>): Promise<Application>;
    changeStage(id: string, stageId: string): Promise<Application>;
    bindResume(id: string, resumeId: string): Promise<Application>;
    updateNote(id: string, note: string): Promise<Application>;
    listTimeline(id: string): Promise<any[]>;
    listResumeUsageHistory(id: string): Promise<any[]>;
    previewArchive(id: string): Promise<ActionPreview>;
    confirmArchive(id: string, preview: ActionPreview): Promise<Application>;
    previewDelete(id: string): Promise<ActionPreview>;
    confirmDelete(id: string, preview: ActionPreview): Promise<void>;
  };
  stageService?: {
    ensureDefaultStages(): Promise<Stage[]>;
    listStages(): Promise<Stage[]>;
    updateStage(id: string, patch: Record<string, unknown>): Promise<Stage>;
    reorderStages(ids: readonly string[]): Promise<Stage[]>;
    previewDelete(id: string): Promise<{ id: string; name: string; kind: string; applicationCount: number }>;
    deleteStage(id: string, options?: Record<string, unknown>): Promise<void>;
    getOutcomeCounts(): Promise<{ offer: number; rejected: number; withdrawn: number }>;
  };
  jobDescriptionService?: {
    ingestPaste(applicationId: string, text: string): Promise<any>;
    ingestFile?: (applicationId: string, file: File) => Promise<any>;
    confirmText(jobDescriptionId: string, text: string): Promise<any>;
  };
  resumeLibrary?: Pick<ResumeLibraryService, "search">;
}

type ActionPreview = { id: string; company?: string; position?: string; name?: string; resumeUsageCount?: number; timelineEventCount?: number; applicationCount?: number; archived?: boolean; kind?: string };

const JOB_TYPES = ["graduate", "internship", "tech", "general", "other"] as const;
const WORK_MODES = ["onsite", "remote", "hybrid", "unknown"] as const;

const defaultApplicationService = {
  listApplications: async () => [] as Application[],
  createApplication: async (input: Record<string, unknown>) => ({ ...input, id: crypto.randomUUID(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() } as Application),
  updateApplication: async (id: string, patch: Record<string, unknown>) => ({ ...patch, id } as Application),
  changeStage: async () => undefined as never,
  bindResume: async () => undefined as never,
  updateNote: async () => undefined as never,
  listTimeline: async () => [],
  listResumeUsageHistory: async () => [],
  previewArchive: async () => undefined as never,
  confirmArchive: async () => undefined as never,
  previewDelete: async () => undefined as never,
  confirmDelete: async () => undefined,
};

const defaultStageService = {
  ensureDefaultStages: async () => [] as Stage[],
  listStages: async () => [] as Stage[],
  updateStage: async () => undefined as never,
  reorderStages: async () => [],
  previewDelete: async () => undefined as never,
  deleteStage: async () => undefined,
  getOutcomeCounts: async () => ({ offer: 0, rejected: 0, withdrawn: 0 }),
};

export function createApplicationBoard(
  documentRef: Document,
  options: ApplicationBoardOptions = {},
): HTMLElement {
  const applicationService = options.applicationService ?? defaultApplicationService;
  const stageService = options.stageService ?? defaultStageService;
  const root = documentRef.createElement("section");
  root.className = "application-board";
  root.setAttribute("aria-labelledby", "application-board-title");
  root.innerHTML = `
    <div class="section-heading application-board__heading">
      <div><p class="section-label">申请管理</p><h2 id="application-board-title">职位申请</h2></div>
      <div class="application-board__controls">
        <button type="button" data-view="board" aria-pressed="true">看板</button>
        <button type="button" data-view="list" aria-pressed="false">列表</button>
        <label for="application-job-type">筛选职位类型</label>
        <select id="application-job-type"><option value="">全部类型</option>${JOB_TYPES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select>
      </div>
    </div>
    <div class="application-board__status" role="status" aria-live="polite" aria-atomic="true">正在读取职位...</div>
    <form class="application-form" data-form="application">
      <div class="application-form__header"><h3 data-form-title>创建职位</h3><button type="button" data-action="cancel-edit" hidden>取消编辑</button></div>
      <div class="application-form__grid">
        <label for="application-company">公司<input id="application-company" name="company" required /></label>
        <label for="application-position">职位<input id="application-position" name="position" required /></label>
        <label>职位类型<select name="jobType">${JOB_TYPES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select></label>
        <label>地点<input name="location" /></label>
        <label>工作模式<select name="workMode">${WORK_MODES.map((value) => `<option value="${value}">${value}</option>`).join("")}</select></label>
        <label>薪资<input name="salaryText" /></label>
        <label>来源<input name="source" /></label>
        <label for="application-job-url">招聘网址<input id="application-job-url" name="jobUrl" type="url" /></label>
        <label>截止时间<input name="deadline" type="datetime-local" /></label>
        <label>联系人<input name="contact" /></label>
        <label>优先级<input name="priority" type="number" min="0" step="1" value="0" /></label>
        <label>阶段<select name="stageId"></select></label>
        <label>当前简历<select name="currentResumeId"><option value="">暂不绑定</option></select></label>
      </div>
      <label>职位备注<textarea name="note" rows="2"></textarea></label>
      <label for="application-jd-text">确认 JD 文本<textarea id="application-jd-text" name="jdText" rows="5" placeholder="粘贴职位描述"></textarea></label>
      <label class="application-file-label">上传 JD（PDF/DOCX）<input name="jdFile" type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" /></label>
      <div class="application-form__actions"><button type="submit" data-submit-application>保存职位</button><button type="button" data-action="confirm-jd" hidden>确认 JD 文本</button></div>
    </form>
    <div class="application-board-view" data-view-panel="board"></div>
    <div class="application-list-view" data-view-panel="list" hidden></div>
    <section class="stage-manager" aria-labelledby="stage-manager-title">
      <div class="section-heading"><h3 id="stage-manager-title">阶段管理</h3><span class="stage-outcome-counts" role="status"></span></div>
      <div class="stage-manager__list"></div>
    </section>
    <section class="application-detail" aria-labelledby="application-detail-title" hidden>
      <div class="section-heading"><h3 id="application-detail-title">职位详情</h3><button type="button" data-action="close-detail">关闭</button></div>
      <div class="application-detail__content"></div>
    </section>
    <div class="application-confirm" role="dialog" aria-modal="true" aria-labelledby="application-confirm-title" hidden>
      <h3 id="application-confirm-title">确认操作</h3><p data-confirm-summary></p>
      <div><button type="button" data-action="confirm-application-action">确认</button><button type="button" data-action="cancel-application-action">取消</button></div>
    </div>
  `;

  const status = root.querySelector<HTMLElement>(".application-board__status")!;
  const board = root.querySelector<HTMLElement>('[data-view-panel="board"]')!;
  const list = root.querySelector<HTMLElement>('[data-view-panel="list"]')!;
  const form = root.querySelector<HTMLFormElement>('form[data-form="application"]')!;
  const detail = root.querySelector<HTMLElement>(".application-detail")!;
  const detailContent = root.querySelector<HTMLElement>(".application-detail__content")!;
  const confirmDialog = root.querySelector<HTMLElement>(".application-confirm")!;
  const confirmSummary = root.querySelector<HTMLElement>("[data-confirm-summary]")!;
  const stageSelect = form.elements.namedItem("stageId") as HTMLSelectElement;
  const resumeSelect = form.elements.namedItem("currentResumeId") as HTMLSelectElement;
  let applications: Application[] = [];
  let stages: Stage[] = [];
  let resumes: Resume[] = [];
  let view: "board" | "list" = "board";
  let filter = "";
  let editingId: string | undefined;
  let detailId: string | undefined;
  let pendingAction: { type: "archive" | "delete" | "stage-delete"; id: string; preview: ActionPreview; replacementStageId?: string } | undefined;
  let pendingJobDescriptionId: string | undefined;

  const esc = (value: unknown): string => String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char] ?? char));
  const visibleApplications = () => applications.filter((item) => !filter || item.jobType === filter);
  const stageById = (id: string) => stages.find((stage) => stage.id === id);
  const setStatus = (message: string) => { status.textContent = message; };

  function renderApplications(): void {
    const items = visibleApplications();
    board.innerHTML = stages.map((stage) => {
      const cards = items.filter((item) => item.stageId === stage.id).map((item) => `
        <article class="application-card" data-application-id="${esc(item.id)}">
          <h4>${esc(item.company)}</h4><p>${esc(item.position)}</p>
          <p class="application-card__meta">${esc(item.location)} · ${esc(item.jobType)} · ${esc(item.workMode)}</p>
          <p class="application-card__stage" style="--stage-color:${esc(stage.color)}">${esc(stage.name)}</p>
          <p class="application-card__resume">${item.currentResumeId ? `简历：${esc(resumes.find((resume) => resume.id === item.currentResumeId)?.name ?? item.currentResumeId)}` : "未绑定简历"}</p>
          <div class="application-card__actions"><button type="button" data-action="details" data-application-id="${esc(item.id)}">查看详情</button><button type="button" data-action="edit" data-application-id="${esc(item.id)}">编辑</button><button type="button" data-action="advance" data-application-id="${esc(item.id)}">推进阶段</button></div>
        </article>`).join("");
      return `<section class="application-stage-column" data-stage-id="${esc(stage.id)}"><h3><span style="--stage-color:${esc(stage.color)}">${esc(stage.name)}</span><small>${cards ? cards.match(/class="application-card"/g)?.length ?? 0 : 0}</small></h3>${cards || `<p class="application-empty">暂无职位</p>`}</section>`;
    }).join("");
    list.innerHTML = items.map((item) => {
      const stage = stageById(item.stageId);
      return `<article class="application-list-row"><div><strong>${esc(item.company)}</strong><span>${esc(item.position)}</span></div><div>${esc(stage?.name ?? "未知阶段")}</div><div>${esc(item.jobType)}</div><div class="application-row-actions"><button type="button" data-action="details" data-application-id="${esc(item.id)}">详情</button><button type="button" data-action="edit" data-application-id="${esc(item.id)}">编辑</button><button type="button" data-action="advance" data-application-id="${esc(item.id)}">推进</button></div></article>`;
    }).join("") || `<p class="application-empty">暂无职位</p>`;
    board.hidden = view !== "board";
    list.hidden = view !== "list";
    root.querySelectorAll<HTMLButtonElement>("[data-view]").forEach((button) => {
      button.setAttribute("aria-pressed", String(button.dataset.view === view));
    });
    setStatus(`${items.length} 个职位，当前为${view === "board" ? "看板" : "列表"}视图`);
  }

  async function renderStages(): Promise<void> {
    const manager = root.querySelector<HTMLElement>(".stage-manager__list")!;
    manager.innerHTML = stages.map((stage, index) => `<div class="stage-manager__item" data-stage-id="${esc(stage.id)}"><label>阶段名称<input data-stage-name value="${esc(stage.name)}" /></label><label>颜色<input data-stage-color type="color" value="${esc(stage.color)}" /></label><button type="button" data-action="save-stage">保存</button><button type="button" data-action="move-stage-up" ${index === 0 ? "disabled" : ""}>上移</button><button type="button" data-action="move-stage-down" ${index === stages.length - 1 ? "disabled" : ""}>下移</button>${stage.kind === "normal" ? `<button type="button" data-action="delete-stage">删除</button>` : ""}</div>`).join("");
    const counts = await stageService.getOutcomeCounts();
    const countElement = root.querySelector<HTMLElement>(".stage-outcome-counts")!;
    countElement.textContent = `Offer ${counts.offer} · 拒绝 ${counts.rejected} · 放弃 ${counts.withdrawn}`;
    stageSelect.innerHTML = stages.map((stage) => `<option value="${esc(stage.id)}">${esc(stage.name)}</option>`).join("");
  }

  async function load(): Promise<void> {
    try {
      if (stageService.ensureDefaultStages) await stageService.ensureDefaultStages();
      [applications, stages] = await Promise.all([applicationService.listApplications(), stageService.listStages()]);
      resumes = options.resumeLibrary ? await options.resumeLibrary.search("") : [];
      resumeSelect.innerHTML = `<option value="">暂不绑定</option>${resumes.filter((resume) => resume.status !== "deleted").map((resume) => `<option value="${esc(resume.id)}">${esc(resume.name)}</option>`).join("")}`;
      await renderStages();
      renderApplications();
    } catch (error) { setStatus(error instanceof Error ? error.message : "职位读取失败"); }
  }

  function resetForm(): void {
    form.reset();
    editingId = undefined;
    (form.querySelector("[data-form-title]") as HTMLElement).textContent = "创建职位";
    (form.querySelector('[data-action="cancel-edit"]') as HTMLButtonElement).hidden = true;
    if (stages[0]) stageSelect.value = stages[0].id;
  }

  async function showDetail(id: string): Promise<void> {
    const item = applications.find((entry) => entry.id === id);
    if (!item) return;
    detailId = id;
    const [timeline, history] = await Promise.all([applicationService.listTimeline(id), applicationService.listResumeUsageHistory(id)]);
    detailContent.innerHTML = `<dl class="application-detail__facts"><dt>公司</dt><dd>${esc(item.company)}</dd><dt>职位</dt><dd>${esc(item.position)}</dd><dt>阶段</dt><dd>${esc(stageById(item.stageId)?.name ?? "")}</dd><dt>网址</dt><dd>${item.jobUrl ? `<a href="${esc(item.jobUrl)}" target="_blank" rel="noreferrer">${esc(item.jobUrl)}</a>` : "未填写"}</dd><dt>JD</dt><dd class="application-long-text">${esc(item.jdText || "未确认 JD")}</dd></dl><div class="application-detail__actions"><label>推进阶段<select data-detail-stage>${stages.map((stage) => `<option value="${esc(stage.id)}" ${stage.id === item.stageId ? "selected" : ""}>${esc(stage.name)}</option>`).join("")}</select></label><button type="button" data-action="save-detail-stage">保存阶段</button><label>切换当前简历<select data-detail-resume><option value="">未绑定</option>${resumes.filter((resume) => resume.status !== "deleted").map((resume) => `<option value="${esc(resume.id)}" ${resume.id === item.currentResumeId ? "selected" : ""}>${esc(resume.name)}</option>`).join("")}</select></label><button type="button" data-action="save-detail-resume">保存简历</button><label>添加备注<textarea data-detail-note rows="2">${esc(item.note)}</textarea></label><button type="button" data-action="save-detail-note">保存备注</button><button type="button" data-action="archive" data-application-id="${esc(id)}">归档</button><button type="button" data-action="delete" data-application-id="${esc(id)}">删除职位</button></div><h4>简历使用历史</h4><ul>${history.map((entry) => `<li>${esc(entry.resumeNameSnapshot)}：${esc(entry.textSnapshot)}</li>`).join("") || "<li>暂无历史</li>"}</ul><h4>时间线</h4><ol>${timeline.map((entry) => `<li>${esc(entry.type)}：${esc(entry.note)}</li>`).join("") || "<li>暂无事件</li>"}</ol>`;
    detail.hidden = false;
  }

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const deadlineValue = String(data.get("deadline") ?? "");
    const input = { company: String(data.get("company") ?? "").trim(), position: String(data.get("position") ?? "").trim(), jobType: String(data.get("jobType") ?? "other") as Application["jobType"], location: String(data.get("location") ?? ""), workMode: String(data.get("workMode") ?? "unknown") as Application["workMode"], salaryText: String(data.get("salaryText") ?? ""), source: String(data.get("source") ?? ""), jobUrl: String(data.get("jobUrl") ?? ""), deadline: deadlineValue ? new Date(deadlineValue).toISOString() : undefined, contact: String(data.get("contact") ?? ""), priority: Number(data.get("priority") ?? 0), note: String(data.get("note") ?? ""), stageId: String(data.get("stageId") ?? stages[0]?.id ?? ""), jdText: String(data.get("jdText") ?? "") };
    try {
      let saved: Application;
      if (editingId) {
        const nextStageId = input.stageId;
        const metadata = { ...input } as Record<string, unknown>;
        delete metadata.stageId;
        delete metadata.jdText;
        saved = await applicationService.updateApplication(editingId, metadata);
        if (nextStageId && saved.stageId !== nextStageId) saved = await applicationService.changeStage(editingId, nextStageId);
      } else {
        saved = await applicationService.createApplication(input as never);
      }
      const resumeId = String(data.get("currentResumeId") ?? "");
      if (resumeId && saved.currentResumeId !== resumeId) saved = await applicationService.bindResume(saved.id, resumeId);
      const file = (data.get("jdFile") as File | null);
      if (file && file.size && options.jobDescriptionService?.ingestFile) {
        const result = await options.jobDescriptionService.ingestFile(saved.id, file);
        pendingJobDescriptionId = result.jobDescription.id;
        if (result.extractedText) {
          (form.elements.namedItem("jdText") as HTMLTextAreaElement).value = result.extractedText.text;
        }
        (form.querySelector('[data-action="confirm-jd"]') as HTMLButtonElement).hidden = false;
        setStatus(result.extractedText ? "JD 已提取，请确认文本后再继续" : "JD 提取失败，请粘贴或校正后确认");
      } else if (editingId && options.jobDescriptionService && input.jdText.trim()) {
        const existingText = saved.jdText;
        if (existingText !== input.jdText) {
          const pasted = await options.jobDescriptionService.ingestPaste(saved.id, input.jdText);
          await options.jobDescriptionService.confirmText(pasted.jobDescription.id, input.jdText);
        }
      }
      if (!pendingJobDescriptionId) resetForm();
      applications = await applicationService.listApplications();
      renderApplications();
      setStatus("职位已保存");
    } catch (error) { setStatus(error instanceof Error ? error.message : "职位保存失败"); }
  });

  root.addEventListener("click", async (event) => {
    const target = (event.target as HTMLElement).closest<HTMLElement>("[data-action], [data-view]");
    if (!target) return;
    const action = target.dataset.action;
    try {
      if (target.dataset.view) { view = target.dataset.view as "board" | "list"; renderApplications(); return; }
      if (action === "confirm-jd" && pendingJobDescriptionId && options.jobDescriptionService) {
        const text = (form.elements.namedItem("jdText") as HTMLTextAreaElement).value;
        await options.jobDescriptionService.confirmText(pendingJobDescriptionId, text);
        pendingJobDescriptionId = undefined;
        (form.querySelector('[data-action="confirm-jd"]') as HTMLButtonElement).hidden = true;
        applications = await applicationService.listApplications();
        renderApplications();
        setStatus("JD 文本已确认");
        resetForm();
        return;
      }
      if (action === "details" && target.dataset.applicationId) { await showDetail(target.dataset.applicationId); return; }
      if (action === "edit" && target.dataset.applicationId) {
        const item = applications.find((entry) => entry.id === target.dataset.applicationId);
        if (!item) return;
        editingId = item.id;
        for (const [name, value] of Object.entries(item)) {
          const field = form.elements.namedItem(name) as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | null;
          if (field && value !== undefined && name !== "id" && name !== "createdAt" && name !== "updatedAt") field.value = name === "deadline" && value ? String(value).slice(0, 16) : String(value);
        }
        resumeSelect.value = item.currentResumeId ?? "";
        stageSelect.value = item.stageId;
        (form.querySelector("[data-form-title]") as HTMLElement).textContent = "编辑职位";
        (form.querySelector('[data-action="cancel-edit"]') as HTMLButtonElement).hidden = false;
        (form.elements.namedItem("jdText") as HTMLTextAreaElement).value = item.jdText;
        form.scrollIntoView({ block: "start" });
        setStatus("已载入职位编辑，尚未保存修改");
        return;
      }
      if (action === "close-detail") { detail.hidden = true; detailId = undefined; return; }
      if (action === "advance" && target.dataset.applicationId) {
        const item = applications.find((entry) => entry.id === target.dataset.applicationId); const index = stages.findIndex((stage) => stage.id === item?.stageId); const next = stages[index + 1];
        if (item && next) { await applicationService.changeStage(item.id, next.id); applications = await applicationService.listApplications(); renderApplications(); setStatus("阶段已推进"); }
        return;
      }
      if (action === "save-detail-stage" && detailId) { const value = detail.querySelector<HTMLSelectElement>("[data-detail-stage]")?.value; if (value) await applicationService.changeStage(detailId, value); applications = await applicationService.listApplications(); await showDetail(detailId); setStatus("阶段已保存"); return; }
      if (action === "save-detail-resume" && detailId) { const value = detail.querySelector<HTMLSelectElement>("[data-detail-resume]")?.value; if (value) await applicationService.bindResume(detailId, value); applications = await applicationService.listApplications(); await showDetail(detailId); setStatus("当前简历已保存"); return; }
      if (action === "save-detail-note" && detailId) { const value = detail.querySelector<HTMLTextAreaElement>("[data-detail-note]")?.value ?? ""; await applicationService.updateNote(detailId, value); applications = await applicationService.listApplications(); await showDetail(detailId); setStatus("备注已保存"); return; }
      if ((action === "archive" || action === "delete") && target.dataset.applicationId) {
        const id = target.dataset.applicationId; const preview = action === "archive" ? await applicationService.previewArchive(id) : await applicationService.previewDelete(id); pendingAction = { type: action, id, preview }; confirmSummary.textContent = `将${action === "archive" ? "归档" : "删除"}“${preview.company} / ${preview.position}”，关联历史 ${preview.resumeUsageCount} 条、时间线 ${preview.timelineEventCount} 条。`; confirmDialog.hidden = false; (confirmDialog.querySelector('[data-action="confirm-application-action"]') as HTMLButtonElement).focus(); setStatus("已打开操作预览，尚未修改数据"); return;
      }
      if (action === "cancel-application-action") { confirmDialog.hidden = true; pendingAction = undefined; setStatus("已取消操作，数据未改变"); return; }
      if (action === "confirm-application-action" && pendingAction) { const pending = pendingAction; if (pending.type === "archive") await applicationService.confirmArchive(pending.id, pending.preview as never); else if (pending.type === "delete") await applicationService.confirmDelete(pending.id, pending.preview as never); else await stageService.deleteStage(pending.id, { confirmed: true, replacementStageId: pending.replacementStageId }); confirmDialog.hidden = true; pendingAction = undefined; applications = await applicationService.listApplications(); stages = await stageService.listStages(); await renderStages(); renderApplications(); detail.hidden = true; setStatus(pending.type === "archive" ? "职位已归档" : pending.type === "delete" ? "职位已删除" : "阶段已删除"); return; }
      const stageItem = target.closest<HTMLElement>(".stage-manager__item");
      if (stageItem && action === "save-stage") { const id = stageItem.dataset.stageId!; await stageService.updateStage(id, { name: stageItem.querySelector<HTMLInputElement>("[data-stage-name]")?.value, color: stageItem.querySelector<HTMLInputElement>("[data-stage-color]")?.value }); stages = await stageService.listStages(); await renderStages(); renderApplications(); setStatus("阶段已保存"); return; }
      if (stageItem && (action === "move-stage-up" || action === "move-stage-down")) { const index = stages.findIndex((stage) => stage.id === stageItem.dataset.stageId); const next = action === "move-stage-up" ? index - 1 : index + 1; if (index >= 0 && next >= 0 && next < stages.length) { const ids = stages.map((stage) => stage.id); [ids[index], ids[next]] = [ids[next], ids[index]]; stages = await stageService.reorderStages(ids); await renderStages(); renderApplications(); setStatus("阶段顺序已保存"); } return; }
      if (stageItem && action === "delete-stage") { const id = stageItem.dataset.stageId!; const preview = await stageService.previewDelete(id); const replacement = stages.find((stage) => stage.id !== id); pendingAction = { type: "stage-delete", id, preview, replacementStageId: replacement?.id }; confirmSummary.textContent = `将删除阶段“${preview.name}”，影响 ${preview.applicationCount} 个职位${replacement ? `，并迁移到“${replacement.name}”` : ""}。`; confirmDialog.hidden = false; (confirmDialog.querySelector('[data-action="confirm-application-action"]') as HTMLButtonElement).focus(); setStatus("已打开阶段删除预览，尚未修改数据"); return; }
    } catch (error) { setStatus(error instanceof Error ? error.message : "操作失败"); }
  });

  root.querySelector("#application-job-type")?.addEventListener("change", (event) => { filter = (event.target as HTMLSelectElement).value; renderApplications(); });
  root.querySelector('[data-action="cancel-edit"]')?.addEventListener("click", resetForm);
  void load();
  return root;
}

import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { nextUpdatedTimestamp } from "../../db/timestamps";
import type {
  Resume,
  ResumeText,
  ResumeUsageHistory,
  StoredFile,
} from "../../db/types";
import type { ResumeDownloadData } from "./ingestion";

export interface ResumeLibraryDependencies {
  now?: () => string;
  createId?: () => string;
}

export interface ResumeDeletePreview {
  id: string;
  name: string;
  fileName: string;
  fileSize: number;
  status: Resume["status"];
  hasOriginalFile: boolean;
  confirmedTextLength: number;
}

export interface ResumeConfirmResult {
  resume: Resume;
  text: ResumeText;
}

export interface ResumeMetadataPatch {
  name?: string;
  tags?: string[];
}

function defaultNow(): string {
  return new Date().toISOString();
}

function defaultCreateId(): string {
  return crypto.randomUUID();
}

function normalizeTags(tags: string[] | undefined): string[] | undefined {
  if (!tags) return undefined;
  return [...new Set(tags.map((tag) => tag.trim()).filter(Boolean))];
}

export class ResumeLibraryService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;

  constructor(database: IDBDatabase, dependencies: ResumeLibraryDependencies = {}) {
    this.#database = database;
    this.#now = dependencies.now ?? defaultNow;
    this.#createId = dependencies.createId ?? defaultCreateId;
  }

  async getResume(resumeId: string): Promise<Resume | undefined> {
    return runTransaction(this.#database, STORE_NAMES.resumes, "readonly", (tx) =>
      requestToPromise<Resume | undefined>(tx.objectStore(STORE_NAMES.resumes).get(resumeId)),
    );
  }

  async listResumes(query = ""): Promise<Resume[]> {
    const resumes = await runTransaction(this.#database, STORE_NAMES.resumes, "readonly", (tx) =>
      requestToPromise<Resume[]>(tx.objectStore(STORE_NAMES.resumes).getAll()),
    );
    const needle = query.trim().toLocaleLowerCase();
    return resumes
      .filter((resume) => {
        if (!needle) return true;
        return [resume.name, resume.fileName, ...resume.tags]
          .some((value) => value.toLocaleLowerCase().includes(needle));
      })
      .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  }

  search(query = ""): Promise<Resume[]> {
    return this.listResumes(query);
  }

  list(query = ""): Promise<Resume[]> {
    return this.listResumes(query);
  }

  async getText(resumeId: string, kind: ResumeText["kind"]): Promise<ResumeText | undefined> {
    return runTransaction(this.#database, STORE_NAMES.resumeTexts, "readonly", (tx) =>
      requestToPromise<ResumeText | undefined>(
        tx.objectStore(STORE_NAMES.resumeTexts).index("resumeId_kind").get([resumeId, kind]),
      ),
    );
  }

  async getConfirmedTextRecord(resumeId: string): Promise<ResumeText | undefined> {
    const resume = await this.getResume(resumeId);
    if (resume?.textSource === "manual") return this.getText(resumeId, "manual");
    if (resume?.textSource === "extracted") return this.getText(resumeId, "confirmed");
    const manual = await this.getText(resumeId, "manual");
    const confirmed = await this.getText(resumeId, "confirmed");
    if (!manual) return confirmed;
    if (!confirmed) return manual;
    return manual.updatedAt >= confirmed.updatedAt ? manual : confirmed;
  }

  async getConfirmedText(resumeId: string): Promise<string | undefined> {
    return (await this.getConfirmedTextRecord(resumeId))?.text;
  }

  getResumeText(resumeId: string, kind: ResumeText["kind"] = "confirmed"): Promise<ResumeText | undefined> {
    return kind === "confirmed" ? this.getConfirmedTextRecord(resumeId) : this.getText(resumeId, kind);
  }

  async confirmText(resumeId: string, text: string): Promise<ResumeConfirmResult> {
    const value = text;
    if (!value.trim()) throw new Error("Confirmed resume text cannot be empty.");
    const timestamp = this.#now();
    const result = await runTransaction(
      this.#database,
      [STORE_NAMES.resumes, STORE_NAMES.resumeTexts],
      "readwrite",
      async (tx) => {
        const resumeStore = tx.objectStore(STORE_NAMES.resumes);
        const textStore = tx.objectStore(STORE_NAMES.resumeTexts);
        const resume = await requestToPromise<Resume | undefined>(resumeStore.get(resumeId));
        if (!resume) throw new Error(`Resume not found: ${resumeId}`);
        const extracted = await requestToPromise<ResumeText | undefined>(
          textStore.index("resumeId_kind").get([resumeId, "extracted"]),
        );
        const kind: ResumeText["kind"] = extracted?.text === value ? "confirmed" : "manual";
        const existing = await requestToPromise<ResumeText | undefined>(
          textStore.index("resumeId_kind").get([resumeId, kind]),
        );
        const textRecord: ResumeText = existing
          ? { ...existing, text: value, confirmedAt: timestamp, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) }
          : {
              id: this.#createId(),
              createdAt: timestamp,
              updatedAt: timestamp,
              resumeId,
              kind,
              text: value,
              confirmedAt: timestamp,
            };
        if (existing) await requestToPromise(textStore.put(textRecord));
        else await requestToPromise(textStore.add(textRecord));
        const updatedResume: Resume = {
          ...resume,
          status: "ready",
          textSource: kind === "confirmed" ? "extracted" : "manual",
          textConfirmedAt: timestamp,
          updatedAt: nextUpdatedTimestamp(timestamp, resume.updatedAt),
        };
        await requestToPromise(resumeStore.put(updatedResume));
        return { resume: updatedResume, text: textRecord };
      },
    );
    return result;
  }

  updateText(resumeId: string, text: string): Promise<ResumeConfirmResult> {
    return this.confirmText(resumeId, text);
  }

  async updateMetadata(resumeId: string, patch: ResumeMetadataPatch): Promise<Resume> {
    return runTransaction(this.#database, STORE_NAMES.resumes, "readwrite", async (tx) => {
      const store = tx.objectStore(STORE_NAMES.resumes);
      const resume = await requestToPromise<Resume | undefined>(store.get(resumeId));
      if (!resume) throw new Error(`Resume not found: ${resumeId}`);
      const updated: Resume = {
        ...resume,
        ...(patch.name !== undefined ? { name: patch.name.trim() || resume.name } : {}),
        ...(patch.tags !== undefined ? { tags: normalizeTags(patch.tags) ?? [] } : {}),
        updatedAt: nextUpdatedTimestamp(this.#now(), resume.updatedAt),
      };
      await requestToPromise(store.put(updated));
      return updated;
    });
  }

  rename(resumeId: string, name: string): Promise<Resume> {
    return this.updateMetadata(resumeId, { name });
  }

  setTags(resumeId: string, tags: string[]): Promise<Resume> {
    return this.updateMetadata(resumeId, { tags });
  }

  async getDownloadData(resumeId: string): Promise<ResumeDownloadData> {
    const stored = await this.getStoredFile(resumeId);
    if (!stored) throw new Error("The original resume file is unavailable.");
    return { blob: stored.blob, fileName: stored.fileName, mimeType: stored.blob.type };
  }

  async getStoredFile(resumeId: string): Promise<StoredFile | undefined> {
    return runTransaction(this.#database, STORE_NAMES.originalFiles, "readonly", (tx) =>
      requestToPromise<StoredFile | undefined>(
        tx.objectStore(STORE_NAMES.originalFiles).index("ownerType_ownerId").get(["resume", resumeId]),
      ),
    );
  }

  async exportConfirmedText(resumeId: string): Promise<Blob> {
    const text = await this.getConfirmedText(resumeId);
    if (text === undefined) throw new Error("No confirmed resume text is available.");
    return new Blob([text], { type: "text/plain;charset=utf-8" });
  }

  exportText(resumeId: string): Promise<Blob> {
    return this.exportConfirmedText(resumeId);
  }

  async previewDelete(resumeId: string): Promise<ResumeDeletePreview> {
    const resume = await this.getResume(resumeId);
    if (!resume) throw new Error(`Resume not found: ${resumeId}`);
    const stored = await this.getStoredFile(resumeId);
    const text = await this.getConfirmedText(resumeId);
    return {
      id: resume.id,
      name: resume.name,
      fileName: resume.fileName,
      fileSize: resume.fileSize,
      status: resume.status,
      hasOriginalFile: Boolean(stored),
      confirmedTextLength: text?.length ?? 0,
    };
  }

  async deleteResume(
    resumeId: string,
    options: { confirmed?: boolean; deleteOriginalFile?: boolean } = {},
  ): Promise<void> {
    if (!options.confirmed) throw new ResumeDeletionConfirmationRequired();
    await runTransaction(
      this.#database,
      [STORE_NAMES.resumes, STORE_NAMES.originalFiles],
      "readwrite",
      async (tx) => {
        const resumeStore = tx.objectStore(STORE_NAMES.resumes);
        const resume = await requestToPromise<Resume | undefined>(resumeStore.get(resumeId));
        if (!resume) throw new Error(`Resume not found: ${resumeId}`);
        const updated: Resume = {
          ...resume,
          status: "deleted",
          updatedAt: nextUpdatedTimestamp(this.#now(), resume.updatedAt),
        };
        await requestToPromise(resumeStore.put(updated));
        if (options.deleteOriginalFile !== false) {
          const files = tx.objectStore(STORE_NAMES.originalFiles);
          const stored = await requestToPromise<StoredFile | undefined>(
            files.index("ownerType_ownerId").get(["resume", resumeId]),
          );
          if (stored) await requestToPromise(files.delete(stored.id));
        }
      },
    );
  }

